import{t as e}from"./utils-COoNfFoj.js";var t={slug:`gen-she`,influencerName:`Gen She`,influencerHandle:`@GenShe`,influencerAvatarUrl:`${e}/gen-she-avatar.jpeg`,heroDescription:`I wanted to build this because I’ve seen firsthand that cold messaging can completely change the trajectory of your career, but most people get stuck on who to reach out to and don’t follow up enough to see results. This dashboard makes that process simple and consistent, so anyone can turn a few messages into real opportunities!`,assetTitle:`Gen She's Cold Outreach operating system`,screenshotUrl:`${e}/gen-she.png`,remixUrl:`https://www.perplexity.ai/apps/ef45fa80-a33b-44b3-ab5c-f8fa9d9316c8`,promptTitle:`Try GenShe's prompt`,promptText:`Build a cold outreach operating system web app that helps me find high-value people, send sharper outreach, and automate follow-ups to turn cold messages into real conversations; include a Lead Radar that ranks prospects by live signals (recent posts, hiring clues, mutual context, engagement), a Sequence Lab for building multi-step cadences across email and LinkedIn with smart delays, a DM Studio that drafts personalized messages using lead signals and proof points, a Warm Queue that auto-promotes leads as heat bars update from profile views, opens, clicks, and replies, a Command Deck homepage surfacing daily KPIs (messages sent, reply rate, warm leads, follow-ups due) alongside a "Today's Flow" action list and quick-launch sequence chips (Cold intro, Proof bump, Soft nudge, Creator collab), a simulated LinkedIn OAuth connector for syncing prospects, all presented in a dark mode SPA UI with deep navy backgrounds, glassy translucent cards, bold display typography, magenta-to-violet gradient accents, a toggleable Y2K mode, and intuitive filters for signal strength, sequence stage, and lead wave.`};export{t as default};
